package com.nvv.mediadata.data.service.firebaseimport android.util.Logimport com.google.firebase.crashlytics.FirebaseCrashlyticsimport timber.log.Timberclass CrashlyticsTree : Timber.Tree() {	override fun log(		priority: Int,		tag: String?,		message: String,		t: Throwable?	) {		if (priority == Log.VERBOSE || priority == Log.DEBUG) return		val crashlytics = FirebaseCrashlytics.getInstance()		crashlytics.setCustomKey("tag", tag ?: "Timber")		crashlytics.log(			"[${priorityToString(priority)}] ${tag ?: ""}: $message"		)		if (t != null && (priority == Log.ERROR || priority == Log.ASSERT)) {			crashlytics.recordException(t)		}	}	private fun priorityToString(priority: Int): String {		return when (priority) {			Log.INFO -> "INFO"			Log.WARN -> "WARN"			Log.ERROR -> "ERROR"			Log.ASSERT -> "ASSERT"			else -> "UNKNOWN"		}	}}